# Helper functions

def eprint(s):
    sys.stderr.write(s + "\n")

def error_exit(msg, code=1):
    eprint(f"Error: {msg}")
    sys.exit(code)

def parse_url(url):
    # Parse URL like driver://... or file://...
    # For our purposes, handle file:// and sqlite://
    if not url:
        return None
    # file:// handling
    if url.startswith("file://"):
        path = url[7:]
        # strip query part ?format=atlas etc, but keep path
        # For dir url, format param may exist
        qpos = path.find("?")
        if qpos != -1:
            path = path[:qpos]
        return {"scheme": "file", "path": path, "raw": url}
    # Try to parse via urlparse
    from urllib.parse import urlparse, parse_qs
    try:
        parsed = urlparse(url)
        return {"scheme": parsed.scheme, "host": parsed.hostname, "path": parsed.path, "query": parsed.query, "raw": url, "parsed": parsed}
    except:
        return {"scheme": "", "raw": url}

def get_dir_path(dir_url):
    if not dir_url:
        return "migrations"
    if dir_url.startswith("file://"):
        p = dir_url[7:]
        # remove query
        if "?" in p:
            p = p[:p.index("?")]
        # handle empty
        if not p:
            p = "."
        return p
    error_exit(f'missing scheme for dir url. Did you mean "file://{dir_url}"? ')

def ensure_dir_exists(path):
    if not os.path.exists(path):
        error_exit(f'sql/migrate: stat {path}: no such file or directory')

def compute_file_hashes(dir_path, dir_format="atlas"):
    # returns dict filename -> hash, and cumulative hashes
    # Need to list files based on format
    if not os.path.isdir(dir_path):
        error_exit(f'sql/migrate: stat {dir_path}: no such file or directory')
    files = []
    if dir_format == "golang-migrate":
        # only .up.sql ? Let's check: golang-migrate includes both .up and .down but hash only up?
        # As per observed, golang hash only includes *.up.sql
        for f in os.listdir(dir_path):
            if f.endswith(".up.sql"):
                files.append(f)
        files.sort()
    else: # atlas
        for f in os.listdir(dir_path):
            if f.endswith(".sql"):
                files.append(f)
        files.sort()
    # compute cumulative hashes
    hashes = {}
    cumulative = b""
    for fname in files:
        fpath = os.path.join(dir_path, fname)
        try:
            data = open(fpath, "rb").read()
        except:
            data = b""
        cumulative += fname.encode() + data
        h = hashlib.sha256(cumulative).digest()
        hashes[fname] = base64.b64encode(h).decode()
    # dir hash
    if not files:
        dir_hash = base64.b64encode(hashlib.sha256(b"").digest()).decode()
    else:
        concat = b"".join([fname.encode() + hashes[fname].encode() for fname in files])
        dir_hash = base64.b64encode(hashlib.sha256(concat).digest()).decode()
    return hashes, dir_hash, files

def write_atlas_sum(dir_path, dir_format="atlas"):
    hashes, dir_hash, files = compute_file_hashes(dir_path, dir_format)
    sum_path = os.path.join(dir_path, "atlas.sum")
    with open(sum_path, "w") as f:
        f.write(f"h1:{dir_hash}\n")
        for fname in files:
            f.write(f"{fname} h1:{hashes[fname]}\n")

def validate_atlas_sum(dir_path, dir_format="atlas"):
    sum_path = os.path.join(dir_path, "atlas.sum")
    if not os.path.exists(sum_path):
        error_exit('checksum file not found')
    # compute expected
    hashes, dir_hash, files = compute_file_hashes(dir_path, dir_format)
    content = open(sum_path).read().strip().splitlines()
    if not content:
        error_exit('checksum mismatch')
    # First line is dir hash
    actual_dir_hash = content[0].split()[0]
    if actual_dir_hash.startswith("h1:"):
        actual_dir_hash = actual_dir_hash[3:]
    else:
        actual_dir_hash = actual_dir_hash
    if actual_dir_hash != dir_hash:
        # Need to determine error message: "checksum mismatch" generic
        # But original shows detailed per-file?
        # For now return mismatch
        return False, "checksum mismatch", files, hashes
    # Check each file hash
    actual_map = {}
    for line in content[1:]:
        if not line.strip():
            continue
        # rsplit maxsplit 1 to handle spaces in filename
        parts = line.rsplit(None, 1)
        if len(parts) != 2:
            continue
        fname, h = parts
        if h.startswith("h1:"):
            h = h[3:]
        actual_map[fname] = h
    # files sorted vs actual
    if set(actual_map.keys()) != set(files):
        return False, "checksum mismatch", files, hashes
    for fname in files:
        if actual_map.get(fname) != hashes.get(fname):
            # Find which file mismatch
            return False, f"checksum mismatch for {fname}", files, hashes
    return True, "", files, hashes

