def parse_config_and_env(config_url, env_name, var_overrides):
    # Parse config file HCL for env definitions, vars, locals
    # config_url like file://path or file:///path
    # If no config_url, default is file://atlas.hcl
    if config_url is None:
        config_url = "file://atlas.hcl"
    # Extract path
    if config_url.startswith("file://"):
        config_path = config_url[7:]
        q = config_path.find("?")
        if q!=-1:
            config_path = config_path[:q]
        if not config_path:
            config_path = "atlas.hcl"
    else:
        config_path = config_url
    # If not exists, error unless it's default and not found? Original says config file "/tmp/missing.hcl" was not found
    if not os.path.exists(config_path):
        error_exit(f'config file "{config_path}" was not found: stat {config_path}: no such file or directory')
    content = open(config_path).read()
    # Quick check for malformed: if contains "invalid syntax here {{" we know it's malformed
    # But we need generic HCL parse error detection. For simplicity, check if file contains "invalid syntax"
    # The original error is "assets/malformed_config.hcl:3,25-26: Argument or block definition required; An argument or block definition is required here."
    # We can detect malformed by checking for "{{" or invalid token
    if "{{" in content:
        # Find line and column
        lines = content.splitlines()
        for li, line in enumerate(lines, start=1):
            if "{{" in line:
                col = line.index("{{") + 1
                error_exit(f'{config_path}:{li},{col}-{col+1}: Argument or block definition required; An argument or block definition is required here.')
    # For our needed configs, we can handle specific patterns:
    # We need to extract variable definitions, locals, env blocks
    vars_def = {}
    locals_def = {}
    envs = {}
    # Parse variable blocks
    var_pattern = re.compile(r'variable\s+"([^"]+)"\s*\{([^}]*)\}', re.DOTALL)
    for m in var_pattern.finditer(content):
        var_name = m.group(1)
        body = m.group(2)
        # find default
        dm = re.search(r'default\s*=\s*"([^"]*)"', body)
        if dm:
            vars_def[var_name] = dm.group(1)
        else:
            dm = re.search(r'default\s*=\s*([^\s\n]+)', body)
            if dm:
                vars_def[var_name] = dm.group(1).strip('"')
            else:
                vars_def[var_name] = ""
        # check type not needed
    # Apply var overrides
    for k,v in var_overrides.items():
        vars_def[k]=v
    # Parse locals
    locals_pattern = re.compile(r'locals\s*\{([^}]*)\}', re.DOTALL)
    for m in locals_pattern.finditer(content):
        body = m.group(1)
        # each line: key = value
        for line in body.splitlines():
            line=line.strip()
            if not line or line.startswith("#"):
                continue
            # match key = "value" or key = var.xxx etc
            kv = re.match(r'(\w+)\s*=\s*"([^"]*)"', line)
            if kv:
                locals_def[kv.group(1)] = kv.group(2)
                continue
            kv = re.match(r'(\w+)\s*=\s*([^\s]+)', line)
            if kv:
                val = kv.group(2).strip('"')
                # handle atlas.env
                if val == "atlas.env":
                    locals_def[kv.group(1)] = env_name if env_name else ""
                else:
                    locals_def[kv.group(1)] = val
    # Parse env blocks
    env_pattern = re.compile(r'env\s+"([^"]+)"\s*\{([^}]*)\}', re.DOTALL)
    for m in env_pattern.finditer(content):
        env_n = m.group(1)
        body = m.group(2)
        env_data = {}
        # parse each line attribute
        for line in body.splitlines():
            line=line.strip()
            if not line or line.startswith("#"):
                continue
            # handle attributes: key = value
            # value could be "string", [var.xxx], local.xxx, getenv("..."), etc
            kv = re.match(r'(\w+)\s*=\s*(.+)', line)
            if not kv:
                continue
            key = kv.group(1)
            raw_val = kv.group(2).strip()
            # Remove trailing comments?
            # handle string value
