                    vname = m.group(1)
                    return vars_def.get(vname, "")
                val = re.sub(r'\$\{var\.([^}]+)\}', lambda m: vars_def.get(m.group(1), ""), val)
                # handle ${local...}? not needed
                env_data[key]=val
            elif raw_val.startswith('['):
                # list like [var.schema_name] or ["main"]
                # Extract items inside brackets
                inner = raw_val.strip('[]').strip()
                items = []
                if inner:
                    # split by comma
                    for item in inner.split(','):
                        item=item.strip().strip('"')
                        # handle var.
                        if item.startswith("var."):
                            vname=item[4:]
                            items.append(vars_def.get(vname,""))
                        else:
                            items.append(item)
                env_data[key]=items
            elif raw_val.startswith('getenv('):
                mm = re.match(r'getenv\("([^"]+)"\)', raw_val)
                if mm:
                    envvar = mm.group(1)
                    env_data[key]=os.getenv(envvar, "")
                else:
                    env_data[key]=""
            elif raw_val.startswith('local.'):
                lname = raw_val[6:].strip()
                # also may have comments? Take first word
                lname = re.split(r'\s', lname)[0]
                env_data[key]=locals_def.get(lname, "")
