def get_env_config(config_url, env_name, var_overrides):
    if not env_name:
        return None
    vars_def, locals_def, envs = parse_config_and_env(config_url, env_name, var_overrides)
    if env_name not in envs:
        error_exit(f'env "{env_name}" not defined in config file')
    return envs[env_name], vars_def, locals_def, envs

def sqlite_url_to_path(url):
    # Handle sqlite://path, sqlite:///tmp/db.db, sqlite://dev?mode=memory, etc
    if url.startswith("sqlite://"):
        rest = url[len("sqlite://"):]
        # Remove query
        qpos = rest.find("?")
        query = rest[qpos:] if qpos!=-1 else ""
        path = rest[:qpos] if qpos!=-1 else rest
        # For mode=memory, path may be dev or empty
        if "mode=memory" in query:
            return ":memory:", query
        if not path:
            return "", query
        # handle absolute path: sqlite:///tmp/db.db -> path is /tmp/db.db (since url is sqlite:// + /tmp/db.db)
        # Our rest for sqlite:///tmp/db.db is "/tmp/db.db" (since after sqlite:// we have "/tmp...")
        # For sqlite://test.db (without leading slash), rest is "test.db"
        # Determine if we should treat as file.
        # If path starts with "/", keep as is, else it's relative.
        # For ":memory:"? Already handled.
        # For "dev?mode=memory" we handled.
        # For "file.db" we return file.db
        return path, query
    elif url.startswith("sqlite:"):
        return url[7:], ""
    else:
        return url, ""

