def compute_file_hashes(dir_path, dir_format="atlas"):
    # returns dict filename -> hash, and cumulative hashes
    # Need to list files based on format
    if not os.path.isdir(dir_path):
        error_exit(f'sql/migrate: stat {dir_path}: no such file or directory')
    files = []
    if dir_format == "golang-migrate":
        # only .up.sql ? Let's check: golang-migrate includes both .up and .down but hash only up?
        # As per observed, golang hash only includes *.up.sql
        for f in os.listdir(dir_path):
            if f.endswith(".up.sql"):
                files.append(f)
        files.sort()
    else: # atlas
        for f in os.listdir(dir_path):
            if f.endswith(".sql"):
                files.append(f)
        files.sort()
    # compute cumulative hashes
    hashes = {}
    cumulative = b""
    for fname in files:
        fpath = os.path.join(dir_path, fname)
        try:
            data = open(fpath, "rb").read()
        except:
            data = b""
        cumulative += fname.encode() + data
        h = hashlib.sha256(cumulative).digest()
        hashes[fname] = base64.b64encode(h).decode()
    # dir hash
    if not files:
        dir_hash = base64.b64encode(hashlib.sha256(b"").digest()).decode()
    else:
        concat = b"".join([fname.encode() + hashes[fname].encode() for fname in files])
        dir_hash = base64.b64encode(hashlib.sha256(concat).digest()).decode()
    return hashes, dir_hash, files

