        if stripped.startswith("#") or stripped.startswith("//"):
            out.append("  "*indent+stripped)
            continue
        if stripped.startswith("}"):
            indent=max(0,indent-1)
        tokens=[]
        i=0
        n=len(stripped)
        while i<n:
            c=stripped[i]
            if c.isspace():
                i+=1
                continue
            if c=='"':
                end=i+1
                while end<n:
                    if stripped[end]=='\\':
                        end+=2
                    elif stripped[end]=='"':
                        end+=1
                        break
                    else:
                        end+=1
                tokens.append(stripped[i:end])
                i=end
                continue
            if c in '={}[],()':
                tokens.append(c)
                i+=1
                continue
            if c=='.':
                tokens.append('.')
                i+=1
                continue
            j=i
            while j<n and not stripped[j].isspace() and stripped[j] not in '"={}[],().' :
                j+=1
            tokens.append(stripped[i:j])
            i=j
        joined=""
        for idx, tok in enumerate(tokens):
            if idx==0:
                joined=tok
                continue
            prev=tokens[idx-1]
            if tok in [",", ")", "]"]:
                joined+=tok
            elif tok=="}":
                joined+=tok
            elif prev in ["(", "["]:
                joined+=tok
            elif tok=="(" :
                if re.match(r'^[a-zA-Z_]', prev):
                    joined+=tok
                else:
                    joined+=" "+tok
            elif tok=="." or prev==".":
                joined+=tok
            elif tok=="{":
