            elif prev=="{":
                joined+=" "+tok
            elif tok=="=" or prev=="=":
                joined+=" "+tok
            else:
                joined+=" "+tok
        out.append("  "*indent+joined)
        if stripped.endswith("{"):
            indent+=1
    return "\n".join(out)+"\n"

