                return set()
            if not os.path.exists(path):
                return set()
            try:
                conn=sqlite3.connect(path)
                cur=conn.cursor()
                cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='atlas_schema_revisions';")
                tbls=set([r[0] for r in cur.fetchall()])
